const deleteUnreferencedOrphanInodes = `-- name: DeleteUnreferencedOrphanInodes :many
DELETE FROM inodes
WHERE ino IN (
    SELECT i.ino
    FROM inodes i
    WHERE i.nlink = 0
      AND NOT EXISTS (
          SELECT 1
          FROM file_handles fh
          LEFT JOIN client_sessions s ON fh.session_id = s.session_id
          WHERE fh.ino = i.ino
            AND (fh.session_id IS NULL OR s.expires_at > clock_timestamp())
      )
    FOR UPDATE SKIP LOCKED
)
RETURNING ino
`

func (q *Queries) DeleteUnreferencedOrphanInodes(ctx context.Context) ([]int64, error) {
	rows, err := q.db.Query(ctx, deleteUnreferencedOrphanInodes)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var ino int64
		if err := rows.Scan(&ino); err != nil {
			return nil, err
		}
		items = append(items, ino)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

